% 同步发电机突然三相短路 .m 数值计算骨架
% 基于论文 EQ-01 定子 a 相电流闭式表达式
% 注:本 .m 骨架为 v0.1 副驾尽力交付层,需用户在 MATLAB 中验证语法与数值正确性

clear; clc;

% --- 参数(由用户从 Simulink 工况或电机初始化结果填入)---
omega = 2 * pi * 50;        % 角频率,fN = 50 Hz
alpha0 = 0;                  % 初相角(α0)— 实际值需由电机初始化工具结果给出,本骨架取 0
t = 0 : 1e-4 : 1;            % 时间序列,采样步长 0.1ms,总长 1s

% --- 衰减时间常数(从论文 EQ-01 公式中读出)---
lambda_freq_1 = -2.97;       % 基频衰减分量 1 的时间常数
lambda_freq_2 = 0.608;       % 基频衰减分量 2 的时间常数(注:论文公式中此项为 +0.608 即增长项,实际仿真应按论文字面取值)
lambda_dc = -6.3;            % 非周期 + 倍频衰减时间常数

% --- a 相电流闭式表达式各分量 ---
i_a_steady = -cos(omega .* t + alpha0);
i_a_freq_decay_1 = -1.4 .* exp(lambda_freq_1 .* t) .* cos(omega .* t + alpha0);
i_a_freq_decay_2 = -2.34 .* exp(lambda_freq_2 .* t) .* cos(omega .* t + alpha0);
i_a_aperiodic = 4 .* exp(lambda_dc .* t) .* cos(-alpha0);
i_a_double_freq = 0.77 .* exp(lambda_dc .* t) .* cos(2 * omega .* t + alpha0);

% --- 总 a 相电流 ---
i_a = i_a_steady + i_a_freq_decay_1 + i_a_freq_decay_2 + i_a_aperiodic + i_a_double_freq;

% --- 分组绘图 ---
figure;
subplot(4, 1, 1); plot(t, i_a); title('a 相定子电流总波形'); xlabel('t (s)'); ylabel('i_a (pu)');
subplot(4, 1, 2); plot(t, i_a_steady + i_a_freq_decay_1 + i_a_freq_decay_2); title('基频分量'); xlabel('t (s)');
subplot(4, 1, 3); plot(t, i_a_double_freq); title('倍频分量'); xlabel('t (s)');
subplot(4, 1, 4); plot(t, i_a_aperiodic); title('非周期分量'); xlabel('t (s)');
